svg.script:
(function () {
  "use strict";

  // The SVG can be opened as a local download, so fetch the source page
  // directly from the repository and point its app assets at the repo CDN.
  const packageBase = "https://cdn.jsdelivr.net/gh/Shazam123abc/sh0zy@main/";
  const pageUrl = "https://raw.githubusercontent.com/Shazam123abc/sh0zy/main/index1.html";
  const oldMainBase = "https://cdn.jsdelivr.net/gh/Shazam123abc/sh0zy@main/";
  const frame = document.getElementById("sift-site");
  const errorPanel = document.getElementById("sift-load-error");
  const errorMessage = document.getElementById("sift-load-error-message");

  function showError(message) {
    errorMessage.textContent = message;
    errorPanel.style.display = "block";
  }

  fetch(pageUrl, { cache: "no-cache" })
    .then(function (response) {
      if (!response.ok) {
        throw new Error("index1.html returned HTTP " + response.status + ".");
      }
      return response.text();
    })
    .then(function (html) {
      if (!/<html[\s>]/i.test(html) || !/<body[\s>]/i.test(html)) {
        throw new Error("index1.html does not look like a complete HTML page.");
      }

      html = html.split(oldMainBase).join(packageBase);

      const baseTag = '<base href="' + packageBase + '">';
      if (/<head(?:\s[^>]*)?>/i.test(html)) {
        html = html.replace(/<head(?:\s[^>]*)?>/i, function (head) {
          return head + baseTag;
        });
      } else {
        html = html.replace(/<html(?:\s[^>]*)?>/i, function (root) {
          return root + "<head>" + baseTag + "</head>";
        });
      }

      frame.srcdoc = html;
    })
    .catch(function (error) {
      showError(error && error.message
        ? error.message
        : "Could not fetch SIFT. Check the repository file and try again.");
    });
})();
